+.page {
+  min-height: 100svh;
+  overflow-x: clip;
+  background:
+    linear-gradient(var(--thorp-line) 1px, transparent 1px),
+    linear-gradient(90deg, var(--thorp-line) 1px, transparent 1px),
+    var(--thorp-background);
+  background-size: 72px 72px, 72px 72px, auto;
+  color: var(--thorp-foreground);
+}
+
+.main {
+  width: min(100% - 40px, 760px);
+  margin: 0 auto;
+  padding: clamp(90px, 15vh, 160px) 0 80px;
+}
+
+.title {
+  margin: 0 0 12px;
+  font-size: clamp(1.7rem, 4.4vw, 2.6rem);
+  line-height: 1.1;
+  letter-spacing: -0.04em;
+}
+
+.lead {
+  margin: 0 0 28px;
+  color: var(--thorp-copy);
+  font-size: clamp(0.92rem, 1.7vw, 1rem);
+  line-height: 1.7;
+}
+
+.loading {
+  margin: 0;
+  color: var(--thorp-copy);
+  font-size: 0.95rem;
+}
+
+/* 아직 줄 것이 없는 상태의 한 문장과 다시 불러오기 행동 하나가 놓이는 자리다. */
+.notice {
+  display: flex;
+  flex-direction: column;
+  align-items: flex-start;
+  gap: 14px;
+  padding: 22px;
+  border: 1px solid var(--thorp-line);
+  border-radius: 14px;
+}
+
+.notice p {
+  margin: 0;
+  color: var(--thorp-copy);
+  font-size: 0.95rem;
+  line-height: 1.7;
+}
+
+.notice button {
+  padding: 9px 16px;
+  border: 1px solid var(--thorp-line);
+  border-radius: 999px;
+  background: transparent;
+  color: inherit;
+  font: inherit;
+  font-size: 0.88rem;
+  cursor: pointer;
+}
+
+.notice button:hover {
+  border-color: currentColor;
+}
+
+.catalog {
+  display: flex;
+  flex-direction: column;
+  gap: 14px;
+}
+
+.listTitle {
+  margin: 0;
+  font-size: 1.05rem;
+  letter-spacing: -0.02em;
+}
+
+/* 목록이 예시 대응표에서 왔다는 표시다. 비중 초깃값 예시 표시와는 다른 자리에 둔다. */
+.sampleNotice {
+  margin: 0;
+  padding: 10px 14px;
+  border: 1px dashed var(--thorp-line);
+  border-radius: 10px;
+  color: var(--thorp-copy);
+  font-size: 0.86rem;
+  line-height: 1.6;
+}
+
+.list {
+  display: grid;
+  gap: 10px;
+  margin: 0;
+  padding: 0;
+  list-style: none;
+}
+
+/* 360px에서도 한 줄로 눌려 넘치지 않게 좁아지면 두 줄로 쌓는다. */
+.item {
+  display: flex;
+  flex-wrap: wrap;
+  align-items: baseline;
+  justify-content: space-between;
+  gap: 6px 12px;
+  padding: 14px 16px;
+  border: 1px solid var(--thorp-line);
+  border-radius: 12px;
+}
+
+.item [data-slot='heading'] {
+  display: inline-flex;
+  align-items: baseline;
+  gap: 8px;
+  min-width: 0;
+}
+
+.item [data-slot='name'] {
+  font-size: 0.98rem;
+  letter-spacing: -0.01em;
+}
+
+.item [data-slot='classification'] {
+  padding: 2px 8px;
+  border: 1px solid var(--thorp-line);
+  border-radius: 999px;
+  color: var(--thorp-copy);
+  font-size: 0.72rem;
+  white-space: nowrap;
+}
+
+.item [data-slot='etf'] {
+  display: inline-flex;
+  align-items: baseline;
+  gap: 6px;
+  min-width: 0;
+  color: var(--thorp-copy);
+  font-size: 0.86rem;
+}
+
+.item [data-slot='etf-label'] {
+  font-size: 0.72rem;
+  opacity: 0.75;
+}
+
+.item [data-slot='etf-name'] {
+  overflow-wrap: anywhere;
+}
+
+.attribution {
+  margin: 4px 0 0;
+  color: var(--thorp-copy);
+  font-size: 0.78rem;
+}
+
+@media (max-width: 600px) {
+  .main {
+    width: min(100% - 28px, 760px);
+    padding-top: 72px;
+  }
+
+  .item {
+    flex-direction: column;
+    align-items: flex-start;
+  }
+}

